window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[22]={"id":"022","numero":22,"titre":"Maladies rares","strategie":{"urgence":"\n<p><strong>Aucune <span class=\"kw-alerte\">urgence vitale</span> propre au champ « maladies rares ».</strong> Le concept de <span class=\"kw-def\">maladie rare</span> est <em>transversal</em> : l'<span class=\"kw-alerte\">urgence</span> dépend de la pathologie sous-jacente (ex. <span class=\"kw-alerte\">crise drépanocytaire</span>, <span class=\"kw-alerte\">décompensation métabolique néonatale</span>, <span class=\"kw-alerte\">insuffisance respiratoire</span> d'une <span class=\"kw-etio\">DMD</span> évoluée).</p>\n<ul>\n  <li>Devant un <strong>tableau atypique inexpliqué</strong> évoluant sur <span class=\"kw-chiffre\">&gt; 1 an</span>, évoquer systématiquement une <span class=\"kw-def\">maladie rare</span> et orienter vers un <span class=\"kw-def\">CRMR</span> (Centre de Référence Maladies Rares).</li>\n  <li>Toute <strong>maladie rare connue qui se décompense</strong> → contacter le <span class=\"kw-def\">CRMR</span> référent du patient (<span class=\"kw-def\">PNDS</span> = protocole d'<span class=\"kw-alerte\">urgence</span> souvent disponible sur le site <span class=\"kw-def\">HAS</span>).</li>\n  <li>Carte d'<span class=\"kw-alerte\">urgence</span> individualisée à <strong>toujours rechercher</strong> chez le patient (<span class=\"kw-def\">Orphanet</span> édite des fiches « Urgences »).</li>\n</ul>","hospit":"\n<p><strong>Architecture de l'offre de soins (<span class=\"kw-def\">PNMR</span> 1, 2, 3) :</strong></p>\n<table>\n  <thead><tr><th>Échelon</th><th>Rôle</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-def\">CRMR</span> coordonnateur</td><td>Centre national pour une <span class=\"kw-def\">maladie rare</span> / un groupe de maladies. Coordination soins, formation, recherche, rédaction des <strong><span class=\"kw-def\">PNDS</span></strong>, <span class=\"kw-ttt\">ETP</span>, alimentation de la <strong><span class=\"kw-def\">BNDMR</span></strong>.</td></tr>\n    <tr><td>Centres constitutifs</td><td>Rattachés au <span class=\"kw-def\">CRMR</span> coordonnateur, financés et évalués.</td></tr>\n    <tr><td><span class=\"kw-def\">CCMR</span> (Centres de Compétences)</td><td>Maillage régional rattaché aux <span class=\"kw-def\">CRMR</span>. <strong>Non financés, non évalués</strong> en tant que tels.</td></tr>\n    <tr><td><span class=\"kw-def\">FSMR</span> (<span class=\"kw-chiffre\">23</span> filières)</td><td>PNMR2. Coordonnent en réseau l'ensemble des CRMR/CCMR + labos + structures sociales + associations d'une thématique.</td></tr>\n    <tr><td><span class=\"kw-def\">ERN</span> (<span class=\"kw-chiffre\">24</span> réseaux européens)</td><td>European Reference Networks. <span class=\"kw-def\">CPMS</span> (clinical patient management system) : « <strong>la connaissance voyage plutôt que le malade</strong> ».</td></tr>\n    <tr><td>Plateformes d'expertise</td><td>Guichet unique régional regroupant les CRMR/CCMR d'un GH ou d'une région.</td></tr>\n  </tbody>\n</table>","redflags":"\n<ul>\n  <li><span class=\"kw-alerte\">Errance diagnostique &gt; 4 ans</span> (concerne <span class=\"kw-chiffre\">25 %</span> des patients) → orientation immédiate vers une <strong>plateforme d'expertise / <span class=\"kw-def\">CRMR</span></strong>.</li>\n  <li><span class=\"kw-alerte\">Tableau atypique de l'enfant</span> avec <span class=\"kw-clinique\">retard de développement</span> / <span class=\"kw-clinique\">dysmorphie</span> / <span class=\"kw-clinique\">atteinte multi-systémique</span> → suspecter une <span class=\"kw-def\">maladie rare</span> (<span class=\"kw-chiffre\"><strong>75 %</strong></span> débutent dans l'enfance, <span class=\"kw-chiffre\"><strong>80 %</strong></span> sont génétiques).</li>\n  <li><span class=\"kw-alerte\">ATCD familiaux récurrents</span> (<span class=\"kw-etio\">consanguinité</span>, <span class=\"kw-alerte\">décès inexpliqués précoces</span>, fratries atteintes) → <span class=\"kw-ttt\">conseil génétique</span> + <span class=\"kw-bio\">analyse moléculaire</span>.</li>\n  <li><span class=\"kw-alerte\"><span class=\"kw-bio\">CK</span> &gt; 100–200 × N chez un garçon</span> avec <span class=\"kw-clinique\">retard moteur</span> ou <span class=\"kw-clinique\">signe de Gowers</span> → suspicion de <span class=\"kw-etio\">dystrophie musculaire de Duchenne</span>.</li>\n  <li><span class=\"kw-alerte\">Impasse diagnostique</span> = échec des investigations conventionnelles → ne pas clôturer le dossier, ré-évaluer à distance (nouvelles techniques <span class=\"kw-bio\">génomiques</span>).</li>\n</ul>","principes":"\n<p><strong>Parcours du patient suspect ou atteint :</strong></p>\n<ol>\n  <li><strong>Point de départ</strong> : patient / entourage informés par les <span class=\"kw-def\">associations</span>, <span class=\"kw-def\">Orphanet</span>, <span class=\"kw-def\">Maladies Rares Info Services</span>.</li>\n  <li><strong>Consultations de 1ᵉʳ recours</strong> : médecin généraliste ou pédiatre → orientation.</li>\n  <li><strong>Consultations spécialisées</strong> : spécialiste d'organe, interniste, <span class=\"kw-def\">généticien clinique</span>.</li>\n  <li><strong>Réseaux hospitaliers</strong> : structure non-experte (1ᵉʳ avis) puis <strong><span class=\"kw-def\">CRMR</span> / <span class=\"kw-def\">CCMR</span></strong> (expertise).</li>\n  <li><strong>Plateformes techniques</strong> : <span class=\"kw-bio\">biochimie</span>, <span class=\"kw-bio\">biologie moléculaire / NGS</span>, tests fonctionnels, <span class=\"kw-imagerie\">imagerie</span>.</li>\n  <li><strong><span class=\"kw-def\">RCP</span> maladie rare</strong> (<span class=\"kw-def\">CRMR</span> + <span class=\"kw-def\">CCMR</span> + filière) → diagnostic final classé : <em>confirmé / probable / possible / absent</em>.</li>\n</ol>\n<p><strong>Outils de PEC :</strong></p>\n<ul>\n  <li><span class=\"kw-def\">PNDS</span> (<span class=\"kw-def\">HAS</span>) : protocoles nationaux diagnostic + soins pour chaque <span class=\"kw-def\">maladie rare</span>.</li>\n  <li><span class=\"kw-ttt\">ETP</span> coordonnée par le <span class=\"kw-def\">CRMR</span>.</li>\n  <li><strong><span class=\"kw-def\">ALD</span> reconnue</strong> sous le libellé « maladie rare » (prise en charge à <span class=\"kw-chiffre\">100 %</span>).</li>\n  <li><span class=\"kw-def\">MDPH</span> + Équipes Relais Handicap Rares (déficits sensoriels/moteurs/cognitifs combinés).</li>\n  <li><strong>Alliance Maladies Rares</strong> : <span class=\"kw-chiffre\">&gt; 200</span> associations fédérées.</li>\n</ul>","suivi":"\n<p><strong><span class=\"kw-def\">Suivi</span> coordonné <span class=\"kw-def\">CRMR</span> ↔ médecin traitant ↔ spécialistes locaux :</strong></p>\n<ul>\n  <li>Rythme et examens définis par le <strong><span class=\"kw-def\">PNDS</span></strong> spécifique à la maladie.</li>\n  <li>Alimentation continue de la <span class=\"kw-def\">BNDMR</span> (Base Nationale de Données Maladies Rares) — <span class=\"kw-def\">épidémiologie</span> en vie réelle.</li>\n  <li><span class=\"kw-def\">Réévaluation</span> diagnostique <strong>périodique en cas d'impasse</strong> (nouvelles techniques <span class=\"kw-bio\">NGS</span>, <span class=\"kw-bio\">exome</span> / <span class=\"kw-bio\">génome</span>).</li>\n  <li>Volet médico-social : <span class=\"kw-def\">ALD</span>, <span class=\"kw-def\">MDPH</span>, AAH/AEEH, scolarité adaptée, insertion professionnelle.</li>\n  <li>Coordination avec l'<strong><span class=\"kw-def\">ERN</span></strong> pour les cas complexes (<span class=\"kw-def\">CPMS</span>, registres européens).</li>\n  <li><span class=\"kw-ttt\">ETP</span> au long cours pour patient + aidants, soutien associatif.</li>\n</ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion de maladie rare","detail":"Tableau atypique, multi-systémique, errance diagnostique &gt; 1 an, ATCD familiaux évocateurs.","branches":[{"to":"info","label":"Étape 1 — Information","color":"blue"}]},{"id":"info","kind":"decision","label":"Patient / entourage","detail":"Associations · Orphanet · Maladies Rares Info Services","branches":[{"to":"premier","label":"Consultation 1ᵉʳ recours","color":"blue"}]},{"id":"premier","kind":"decision","label":"Médecin généraliste / pédiatre","detail":"Évaluation initiale et orientation.","branches":[{"to":"specialiste","label":"Consultation spécialisée","color":"blue"}]},{"id":"specialiste","kind":"decision","label":"Spécialiste / interniste / généticien clinique","detail":"Examen approfondi · prescription d'examens ciblés.","branches":[{"to":"crmr","label":"Orientation vers réseau MR","color":"amber"},{"to":"dx-direct","label":"Diagnostic posé","color":"green"}]},{"id":"dx-direct","kind":"terminal","label":"Diagnostic confirmé","color":"green","detail":"Application du <strong>PNDS</strong> · ALD 100 % au libellé « maladie rare » · suivi coordonné MG ↔ spécialiste ↔ CRMR."},{"id":"crmr","kind":"decision","label":"CRMR / CCMR / Plateforme d'expertise","detail":"Plateformes techniques : biochimie, tests génétiques (NGS, exome), tests fonctionnels, imagerie.","branches":[{"to":"rcp","label":"RCP maladie rare","color":"blue"}]},{"id":"rcp","kind":"decision","label":"Conclusion RCP","detail":"Diagnostic : confirmé / probable / possible / absence de diagnostic.","branches":[{"to":"confirme","label":"Confirmé ou probable","color":"green"},{"to":"possible","label":"Possible","color":"amber"},{"to":"impasse","label":"Aucun diagnostic","color":"red"}]},{"id":"confirme","kind":"terminal","label":"PEC selon PNDS","color":"green","detail":"PNDS (HAS) · ETP · ALD · MDPH si handicap · Alliance Maladies Rares · suivi conjoint CRMR + médecin traitant."},{"id":"possible","kind":"terminal","label":"Surveillance + ré-évaluation","color":"amber","detail":"PEC symptomatique · suivi rapproché CRMR · ré-investigation à distance (nouvelles techniques moléculaires)."},{"id":"impasse","kind":"terminal","label":"Impasse diagnostique","color":"red","detail":"Inclusion dans <strong>registres ERN</strong> · CPMS européen · ré-analyse exome / génome périodique · soutien associatif essentiel."}]},"objectifs":[{"id":"22-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une maladie rare","frequence":1,"contenu":"\n<p><strong>Définition européenne (et française) :</strong> <span class=\"kw-def\">maladie rare</span> = maladie qui atteint <span class=\"kw-chiffre\">moins d'1 personne sur 2 000</span> en population générale.</p>\n<table>\n  <thead><tr><th>Critère</th><th>Valeur</th></tr></thead>\n  <tbody>\n    <tr><td>Seuil de <span class=\"kw-def\">prévalence</span></td><td><span class=\"kw-chiffre\">&lt; 1/2 000</span> habitants</td></tr>\n    <tr><td>Nombre de <span class=\"kw-def\">maladies rares</span> recensées</td><td><span class=\"kw-chiffre\">≈ 8 000</span> maladies</td></tr>\n    <tr><td>Origine <span class=\"kw-etio\">génétique</span></td><td><span class=\"kw-chiffre\">80 %</span> (&gt; <span class=\"kw-chiffre\">3 000</span> gènes identifiés)</td></tr>\n    <tr><td>Début dans l'enfance</td><td><span class=\"kw-chiffre\">75 %</span> des cas</td></tr>\n    <tr><td><span class=\"kw-ttt\">Traitement spécifique</span> disponible</td><td><span class=\"kw-chiffre\">5 %</span> seulement</td></tr>\n  </tbody>\n</table>\n<p>La majorité des <span class=\"kw-def\">maladies rares</span> ne disposent pas de <span class=\"kw-ttt\">traitement étiologique</span> : la PEC est essentiellement <strong>symptomatique et multidisciplinaire</strong>.</p>"},{"id":"22-2","rang":"B","rubrique":"Définition","titre":"Connaître l'organisation des soins des maladies rares en France","frequence":1,"contenu":"\n<p>La France est le <strong>1ᵉʳ pays européen</strong> à s'être doté de <span class=\"kw-def\">plans nationaux maladies rares</span> (<span class=\"kw-def\">PNMR</span>).</p>\n<table>\n  <thead><tr><th>Plan</th><th>Période</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-def\">PNMR 1</span></td><td><span class=\"kw-chiffre\">2004 – 2010</span> (création des <span class=\"kw-def\">CRMR</span>)</td></tr>\n    <tr><td><span class=\"kw-def\">PNMR 2</span></td><td><span class=\"kw-chiffre\">2010 – 2017</span> (création des <span class=\"kw-def\">FSMR</span>)</td></tr>\n    <tr><td><span class=\"kw-def\">PNMR 3</span></td><td>depuis <span class=\"kw-chiffre\">2018</span> (plateformes d'expertise)</td></tr>\n  </tbody>\n</table>\n<p>Portés conjointement par les <strong>Ministères de la Santé et de la Recherche</strong>, en lien avec les associations de patients.</p>\n\n<p><strong>Maillage de l'offre :</strong></p>\n<ul>\n  <li><span class=\"kw-def\">CRMR</span> (Centres de Référence Maladies Rares) — coordonnateurs : missions de soins, formation, recherche, rédaction des <span class=\"kw-def\">PNDS</span>, <span class=\"kw-ttt\">ETP</span>, alimentation de la <strong><span class=\"kw-def\">BNDMR</span></strong>. Composition <span class=\"kw-def\">pluridisciplinaire</span> (médicale, paramédicale, psy, sociale).</li>\n  <li><strong>Centres constitutifs</strong> rattachés à un <span class=\"kw-def\">CRMR</span> coordonnateur (financés + évalués).</li>\n  <li><span class=\"kw-def\">CCMR</span> (Centres de Compétences) : maillage régional, <strong>non financés et non évalués</strong> en tant que tels.</li>\n  <li><span class=\"kw-def\">FSMR</span> — <span class=\"kw-chiffre\">23</span> filières de santé maladies rares (<span class=\"kw-def\">PNMR2</span>) : coordination en réseau de l'ensemble des acteurs (<span class=\"kw-def\">CRMR</span>/<span class=\"kw-def\">CCMR</span>, labos, médico-social, associations) d'une thématique.</li>\n  <li><span class=\"kw-def\">ERN</span> — <span class=\"kw-chiffre\">24</span> réseaux européens de référence. Outil phare : <strong><span class=\"kw-def\">CPMS</span></strong> (clinical patient management system) — <em>« la connaissance voyage plutôt que le malade »</em>. Registres européens partagés.</li>\n  <li><strong>Plateformes d'expertise maladies rares</strong> : guichet unique régional (<span class=\"kw-def\">PNMR3</span>) regroupant les <span class=\"kw-def\">CRMR</span>/<span class=\"kw-def\">CCMR</span> d'un GH ou d'une région.</li>\n</ul>"},{"id":"22-3","rang":"B","rubrique":"Étiologies","titre":"Connaître quelques maladies rares parmi les plus fréquentes","frequence":6,"contenu":"\n<p>Exemple « phare » du référentiel EDN : la <span class=\"kw-etio\">Dystrophie Musculaire de Duchenne (DMD)</span>.</p>\n<table>\n  <thead><tr><th>Item</th><th>Données clés</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-def\">Physiopathologie</span></td><td><strong>Absence totale de <span class=\"kw-def\">dystrophine</span></strong> (variants pathogènes du gène <em>DMD</em>) → <span class=\"kw-clinique\">dégénérescence des muscles squelettiques</span>, lisses et cardiaques → <span class=\"kw-clinique\">atrophie</span> + <span class=\"kw-clinique\">faiblesse musculaire</span>.</td></tr>\n    <tr><td>Transmission</td><td><span class=\"kw-def\">Récessive liée à l'X</span></td></tr>\n    <tr><td>Sex-ratio</td><td>Affecte principalement les <strong>garçons</strong></td></tr>\n    <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">1/3 500 à 1/9 300</span> naissances masculines</td></tr>\n    <tr><td>Âge de début</td><td>Petite enfance</td></tr>\n    <tr><td>Manifestations</td><td>\n      <ul>\n        <li><span class=\"kw-clinique\">Troubles du neuro-développement</span> (après <span class=\"kw-chiffre\">18 mois</span>) : <span class=\"kw-clinique\">retard de langage</span> / développement global.</li>\n        <li><span class=\"kw-etio\">Autisme</span>, <span class=\"kw-clinique\">troubles du comportement</span> (relativement courants).</li>\n        <li><span class=\"kw-clinique\">Marche dandinante</span> · <strong><span class=\"kw-clinique\">signe de Gowers</span></strong> positif.</li>\n        <li><span class=\"kw-alerte\"><strong>Perte de la marche entre <span class=\"kw-chiffre\">6 et 13 ans</span></strong></span> (≈ <span class=\"kw-chiffre\">9,5 ans</span> si non traité par <span class=\"kw-ttt\">stéroïdes</span>).</li>\n      </ul>\n    </td></tr>\n    <tr><td>Diagnostic</td><td>\n      <ol>\n        <li>Suspicion : <span class=\"kw-clinique\">clinique</span> + ATCD familiaux + <span class=\"kw-bio\">CK sériques &gt; 100–200 × N</span>.</li>\n        <li>Confirmation : <strong><span class=\"kw-bio\">analyse génétique</span></strong> du gène <em>DMD</em>.</li>\n      </ol>\n    </td></tr>\n    <tr><td><span class=\"kw-def\">Pronostic</span></td><td><span class=\"kw-alerte\">Sévère</span> : <span class=\"kw-alerte\">espérance de vie significativement réduite</span>, <span class=\"kw-alerte\">décès</span> souvent au début de l'âge adulte (s'améliore grâce à la PEC multidisciplinaire et aux <span class=\"kw-ttt\">corticoïdes</span>).</td></tr>\n  </tbody>\n</table>\n<p><em>D'autres <span class=\"kw-def\">maladies rares</span> à connaître (souvent abordées en transversal) : <span class=\"kw-etio\">drépanocytose</span>, <span class=\"kw-etio\">mucoviscidose</span>, <span class=\"kw-etio\">maladie de Huntington</span>, <span class=\"kw-etio\">syndrome de Marfan</span>, <span class=\"kw-etio\">neurofibromatoses</span>, <span class=\"kw-etio\">amyotrophie spinale</span>, <span class=\"kw-etio\">hémophilie</span>, <span class=\"kw-etio\">syndrome de Rett</span>…</em></p>"},{"id":"22-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des maladies rares","frequence":4,"contenu":"\n<table>\n  <thead><tr><th>Échelle</th><th><span class=\"kw-def\">Prévalence</span> cumulée des <span class=\"kw-def\">maladies rares</span></th></tr></thead>\n  <tbody>\n    <tr><td>France</td><td><span class=\"kw-chiffre\">3 millions</span> de personnes ⭐ (enjeu majeur de santé publique)</td></tr>\n    <tr><td>Europe</td><td><span class=\"kw-chiffre\">30 millions</span></td></tr>\n    <tr><td>Monde</td><td><span class=\"kw-chiffre\">350 millions</span> ⭐ (soit <span class=\"kw-chiffre\">3,5 à 6 %</span> de la population mondiale)</td></tr>\n  </tbody>\n</table>\n<p><strong>Caractéristiques épidémiologiques majeures :</strong></p>\n<ul>\n  <li><span class=\"kw-chiffre\">≈ 8 000</span> <span class=\"kw-def\">maladies rares</span> recensées à ce jour.</li>\n  <li><span class=\"kw-chiffre\">75 %</span> débutent <strong>dans l'enfance</strong> (révélation possible à l'âge adulte mais à impact moindre sur le système de santé).</li>\n  <li><span class=\"kw-chiffre\">80 %</span> sont d'origine <strong><span class=\"kw-etio\">génétique</span></strong> (&gt; <span class=\"kw-chiffre\">3 000</span> gènes identifiés).</li>\n  <li><span class=\"kw-chiffre\">50 %</span> des patients restent sans <span class=\"kw-alerte\">diagnostic précis</span>.</li>\n  <li><span class=\"kw-chiffre\">5 %</span> bénéficient d'un <span class=\"kw-ttt\">traitement spécifique</span> : la majorité est en PEC purement <span class=\"kw-ttt\">symptomatique</span>.</li>\n</ul>\n<p>Bien qu'individuellement rares, leur somme représente une <strong>cause majeure de <span class=\"kw-alerte\">morbi-mortalité</span></strong>, particulièrement en pédiatrie.</p>"},{"id":"22-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la définition de l'errance diagnostique et l'impasse diagnostique","frequence":3,"contenu":"\n<table>\n  <thead><tr><th>Concept</th><th>Définition</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><span class=\"kw-def\">Errance diagnostique</span></td>\n      <td>\n        <strong>Période</strong> qui s'étend de l'<strong>apparition des 1ᵉʳˢ <span class=\"kw-clinique\">symptômes</span></strong> jusqu'à la <strong>date à laquelle un diagnostic précis est posé</strong>.\n        <ul>\n          <li>Délai moyen pour poser un diagnostic : <span class=\"kw-chiffre\">1,5 an</span>.</li>\n          <li><span class=\"kw-alerte\"><span class=\"kw-chiffre\">25 %</span> des patients</span> atteints de <span class=\"kw-def\">maladie rare</span> ont une <strong>errance diagnostique <span class=\"kw-chiffre\">&gt; 4 ans</span></strong>.</li>\n        </ul>\n      </td>\n    </tr>\n    <tr>\n      <td><span class=\"kw-def\">Impasse diagnostique</span></td>\n      <td>\n        <strong>Échec à définir la cause précise</strong> de la maladie après avoir mis en œuvre l'<strong>ensemble des investigations disponibles</strong>.\n        <ul>\n          <li>Concerne notamment :\n            <ul>\n              <li>une <strong>forme atypique</strong> d'une maladie connue ;</li>\n              <li>une maladie dont la <strong>cause <span class=\"kw-etio\">génétique</span> ou autre n'a pas encore été reconnue</strong> ⭐.</li>\n            </ul>\n          </li>\n          <li>Ne pas clôturer le dossier : <strong>ré-évaluation périodique</strong> avec les nouvelles techniques (<span class=\"kw-bio\">NGS</span>, <span class=\"kw-bio\">exome</span>, <span class=\"kw-bio\">génome</span>).</li>\n        </ul>\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p><strong>Conséquences de l'errance / impasse :</strong> <span class=\"kw-alerte\">retard thérapeutique</span>, surcoût, conséquences psycho-sociales lourdes pour le patient et sa famille — justifie l'orientation précoce vers une <strong>plateforme d'expertise / <span class=\"kw-def\">CRMR</span></strong>.</p>"},{"id":"22-6","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge des maladies rares en ville","frequence":0,"contenu":"\n<p><strong>Parcours diagnostique d'un patient en ville :</strong></p>\n<ol>\n  <li><strong>Information du patient et de l'entourage</strong> via les <span class=\"kw-def\">associations</span>, <span class=\"kw-def\">Orphanet</span> et <span class=\"kw-def\">Maladies Rares Info Services</span>.</li>\n  <li><strong>Consultations générales</strong> : médecin généraliste ou pédiatre → orientation.</li>\n  <li><strong>Consultations spécialisées</strong> : spécialistes libéraux d'organe, internistes, <span class=\"kw-def\">généticien clinique</span>.</li>\n  <li><strong>Réseaux hospitaliers</strong> : structure non-experte (1ᵉʳ avis), puis <strong>experts en MR</strong> (<span class=\"kw-def\">CRMR</span>/<span class=\"kw-def\">CCMR</span>).</li>\n  <li><strong>Plateformes techniques</strong> : <span class=\"kw-bio\">biochimie</span>, <span class=\"kw-bio\">biologie moléculaire</span> (<span class=\"kw-bio\">NGS</span>, <span class=\"kw-bio\">exome</span>), tests fonctionnels, <span class=\"kw-imagerie\">imagerie</span>.</li>\n  <li><strong><span class=\"kw-def\">RCP</span> maladie rare</strong> (<span class=\"kw-def\">CRMR</span> + <span class=\"kw-def\">CCMR</span> + filière) : diagnostic <em>confirmé / probable / possible / absent</em>.</li>\n</ol>\n\n<p><strong>Ressources mobilisables :</strong></p>\n<table>\n  <thead><tr><th>Ressource</th><th>Description</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Plateformes d'expertise MR</strong></td><td>Guichet unique régional rassemblant <span class=\"kw-def\">CRMR</span> + <span class=\"kw-def\">CCMR</span> : porte d'entrée unique pour patients et professionnels (diagnostic + orientation).</td></tr>\n    <tr><td><strong><span class=\"kw-def\">Orphanet</span></strong></td><td>Portail web public et gratuit : <span class=\"kw-def\">maladies rares</span>, <span class=\"kw-ttt\">médicaments orphelins</span>, associations, professionnels et centres experts, laboratoires diagnostiques.</td></tr>\n    <tr><td><strong>Maladies Rares Info Services</strong></td><td>Service d'information et de soutien (en ligne + téléphonique) — grand public et professionnels.</td></tr>\n    <tr><td><strong><span class=\"kw-def\">PNDS</span></strong></td><td>Publiés sur le site de la <strong><span class=\"kw-def\">HAS</span></strong> : Protocoles Nationaux de Diagnostic et de Soins pour les principales <span class=\"kw-def\">maladies rares</span> (référentiel de PEC).</td></tr>\n    <tr><td><strong>Alliance Maladies Rares</strong></td><td>Fédère <span class=\"kw-chiffre\">&gt; 200</span> associations : visibilité, qualité de vie, soutien aux associations, promotion de la recherche.</td></tr>\n    <tr><td><strong>PEC médico-sociale</strong></td><td>\n      <ul>\n        <li><span class=\"kw-def\">ALD</span> reconnue sous le libellé « maladie rare » (PEC à <span class=\"kw-chiffre\">100 %</span>).</li>\n        <li><span class=\"kw-def\">MDPH</span> : Maisons Départementales des Personnes Handicapées.</li>\n        <li><strong>Équipes Relais Handicap Rares</strong> : pour les <span class=\"kw-def\">handicaps rares</span> (association rare et simultanée de déficits sensoriels, moteurs, cognitifs et/ou de <span class=\"kw-clinique\">troubles psychiques</span>).</li>\n      </ul>\n    </td></tr>\n  </tbody>\n</table>"}],"astuces":[{"type":"danger","titre":"Le seuil à retenir : 1/2 000","contenu":"Une <strong><span class=\"kw-def\">maladie rare</span> = <span class=\"kw-def\">prévalence</span> <span class=\"kw-chiffre\">&lt; 1/2 000</span></strong> en population générale. Piège classique de QCM : ne pas confondre avec le seuil américain (<strong><span class=\"kw-chiffre\">&lt; 200 000</span> personnes aux USA</strong>) ni avec la définition de l'OMS (variable selon les pays)."},{"type":"danger","titre":"Errance vs Impasse — à ne pas confondre","contenu":"<ul>\n        <li><strong><span class=\"kw-def\">Errance diagnostique</span></strong> = <em>temps</em> entre 1ᵉʳˢ <span class=\"kw-clinique\">symptômes</span> et diagnostic posé (moyenne <span class=\"kw-chiffre\">1,5 an</span>, <span class=\"kw-chiffre\">25 %</span> &gt; <span class=\"kw-chiffre\">4 ans</span>).</li>\n        <li><strong><span class=\"kw-def\">Impasse diagnostique</span></strong> = <em>échec</em> à poser un diagnostic après <strong>toutes</strong> les investigations disponibles (forme atypique ou cause encore inconnue).</li>\n      </ul>"},{"type":"warn","titre":"Chiffres-clés à mémoriser","contenu":"<ul>\n        <li><span class=\"kw-chiffre\">3 millions</span> en France · <span class=\"kw-chiffre\">30 M</span> en Europe · <span class=\"kw-chiffre\">350 M</span> dans le monde.</li>\n        <li><span class=\"kw-chiffre\">8 000</span> <span class=\"kw-def\">maladies rares</span> recensées · <span class=\"kw-chiffre\">80 %</span> <span class=\"kw-etio\">génétiques</span> · <span class=\"kw-chiffre\">75 %</span> débutent dans l'enfance.</li>\n        <li><span class=\"kw-chiffre\">50 %</span> sans diagnostic précis · <span class=\"kw-chiffre\">5 %</span> seulement avec <span class=\"kw-ttt\">traitement spécifique</span>.</li>\n      </ul>"},{"type":"info","titre":"Architecture CRMR / CCMR / FSMR / ERN","contenu":"Hiérarchie à connaître pour les QCM :\n        <ul>\n          <li><strong><span class=\"kw-def\">CRMR</span></strong> coordonnateur (national) ↔ <strong>centres constitutifs</strong> (financés) ↔ <strong><span class=\"kw-def\">CCMR</span></strong> régionaux (<em>non financés, non évalués</em>).</li>\n          <li><strong><span class=\"kw-def\">FSMR</span></strong> (<span class=\"kw-chiffre\">23</span>) = filières thématiques nationales (<span class=\"kw-def\">PNMR2</span>).</li>\n          <li><strong><span class=\"kw-def\">ERN</span></strong> (<span class=\"kw-chiffre\">24</span>) = réseaux européens · outil <strong><span class=\"kw-def\">CPMS</span></strong> : « la connaissance voyage plutôt que le malade ».</li>\n        </ul>"},{"type":"info","titre":"DMD — l'exemple à toujours citer","contenu":"<span class=\"kw-etio\">Dystrophie de Duchenne</span> : <strong><span class=\"kw-def\">récessive liée à l'X</span></strong>, garçons, <strong><span class=\"kw-clinique\">signe de Gowers</span></strong>, <span class=\"kw-alerte\">perte de la marche</span> entre <span class=\"kw-chiffre\">6 et 13 ans</span>, <strong><span class=\"kw-bio\">CK &gt; 100–200 × N</span></strong> à la suspicion, confirmation <span class=\"kw-bio\">génétique</span> du gène <em>DMD</em>. C'est la <span class=\"kw-def\">maladie rare</span> la plus citée en QCM EDN sur l'item 22."},{"type":"tip","titre":"Les 4 outils du patient en ville","contenu":"Mémo « <strong>O.M.P.A.</strong> » pour les ressources clé : <strong><span class=\"kw-def\">O</span>rphanet</strong> · <strong>M</strong>aladies Rares Info Services · <strong><span class=\"kw-def\">P</span>NDS</strong> (<span class=\"kw-def\">HAS</span>) · <strong>A</strong>lliance Maladies Rares. Compléter par <strong><span class=\"kw-def\">ALD</span> <span class=\"kw-chiffre\">100 %</span></strong> au libellé « maladie rare » et orientation <strong><span class=\"kw-def\">MDPH</span></strong>."}],"cards":[]};